// Turns MASKOTKA.svg into mascot.js (inline SVG works on file://, fetch doesn't). Run: node build-mascot.js
const fs = require("fs");
const svg = fs.readFileSync(__dirname + "/MASKOTKA.svg", "utf8")
  .replace(/<\?xml[^>]*>/, "")
  .replace(/<!--[\s\S]*?-->/, "")
  .replace(/<image[\s\S]*?\/>/, "") // hidden reference photo, ~110 KB
  .trim();
fs.writeFileSync(__dirname + "/mascot.js",
  "// Generated by build-mascot.js from MASKOTKA.svg, do not edit.\nwindow.MASCOT_SVG = " + JSON.stringify(svg) + ";\n");
